  '%d render-blocking CSS/JS requests in <head>. Measure the estimated saving with PageSpeed.' => '%d solicitações CSS/JS de bloqueio de renderização em<head>. Meça a economia estimada com o PageSpeed.',
  'The page has %s elements.' => 'A página possui elementos %s.',
  'Response measured from the server: %d ms (may bypass the cache).' => 'Resposta medida do servidor: %d ms (pode ignorar o cache).',
  'HTML is %s.' => 'HTML é %s.',
